"use strict";
const { createHash } = require("crypto");
const target = "62923ccda3a8bcb86b9a446feb430b7a8aa40cfd6c7b87c960a327a8b9ef72ac";
const c = (s) => createHash("sha256").update(s, "utf8").digest("hex");

// Candidate year tokens that contain "_2026"
const yearTokens = ["_2026", "2026", "-2026", "__2026", "_2026_", "_2026x", "x_2026", "2026_", "-_2026", "_2026-", "2 0 2 6"];
// Candidate word slugs
const words = ["quarterly", "report", "Quarterly", "Report", "quarterlyreport", "quarterly-report", "quarterly report", "quarterly.report", "quarterly_report"];
const seps = ["", " ", "-", "_", ".", "~", "--", "  "];

let found = [];
function check(s) {
  if (c(s) === target) found.push(s);
}

// combos: word1 sep word2 sep yearToken (and reversed)
for (const w1 of words)
  for (const s1 of seps)
    for (const w2 of words)
      for (const s2 of seps)
        for (const y of yearTokens) {
          check(w1 + s1 + w2 + s2 + y);
          check(y + s2 + w2 + s1 + w1);
        }

// Also the raw title with one char replaced
const TITLE = "Quarterly Report 2026";
for (let i = 0; i < TITLE.length; i++)
  for (let k = 0; k < 128; k++) {
    const s = TITLE.slice(0, i) + String.fromCharCode(k) + TITLE.slice(i + 1);
    check(s);
  }

// also allow appending/removing one char to the known slug
const base = "quarterly-report-2026";
for (let i = 0; i <= base.length; i++)
  for (let k = 0; k < 128; k++) {
    check(base.slice(0, i) + String.fromCharCode(k) + base.slice(i));
  }

console.log("found:", JSON.stringify(found));

